import time
from functools import wraps

# 1. Timer decorator:
def timer(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start_time = time.perf_counter()
        result = func(*args, **kwargs)
        end_time = time.perf_counter()
        print(f"{func.__name__} took {end_time - start_time:.4f} seconds")
        return result
    return wrapper

# 2. Cache decorator:
def cache(func):
    stored_results = {}
    @wraps(func)
    def wrapper(*args, **kwargs):
        key = str(args) + str(sorted(kwargs.items()))
        if key not in stored_results:
            stored_results[key] = func(*args, **kwargs)
            print(f"Calculating result for {func.__name__}{args}")
        else:
            print(f"Using cached result for {func.__name__}{args}")
        return stored_results[key]
    return wrapper

# 3. Retry decorator:
def retry(max_attempts=3, delay=1):
    def decorator_retry(func):
        @wraps(func)
        def wrapper_retry(*args, **kwargs):
            attempts = 0
            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempts += 1
                    if attempts == max_attempts:
                        raise e
                    print(f"Attempt {attempts} failed: {e}. Retrying...")
                    time.sleep(delay)
            return None
        return wrapper_retry
    return decorator_retry

# 4. Authentication decorator:
def require_auth(role="user"):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            user_role = kwargs.get('user_role', 'guest')
            if user_role == 'admin' or (role == 'user' and user_role in ['user', 'admin']):
                return func(*args, **kwargs)
            else:
                raise PermissionError(f"Access denied. Required role: {role}")
        return wrapper
    return decorator

# 5. Test function with multiple decorators:
@timer
@cache
def expensive_operation(n):
    time.sleep(0.1)  # Simulate expensive operation
    return n * n

# Test the decorated function
print(expensive_operation(5))
print(expensive_operation(5))  # Should use cache
